"""Export six independently reviewable estimated polygons; never modifies registries."""
import json,hashlib
from pathlib import Path
P=Path(__file__).resolve().parent
ID='zalaegerszeg-six-explicit-source-inferences'
def read(n):return json.loads((P/n).read_text())
def write(n,x):(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
fs=read('remaining-manual-world.geojson')['features']+read('remaining-iparterulet-one-pixel-inferred-world.geojson')['features']
for f in fs:
 p=f['properties'];num=p['sourceUnitNumber'];f['id']=f'manual:{ID}:unit-{num}'
 p.update({'id':f['id'],'boundaryKind':'inferred_area','estimated':True,'canonicalNameIsNeighborhood':False,'usableForAddressAssignment':False,'sourceContourIsObserved':False,'reconstructionConfidence':'low','sourceHistoricalUnitIsNeighborhood':True,'sourceHistoricalNameEvidence':'Official municipal ITS figure1/page12, numbered-name table/page13.','reviewStatus':'independent_review_completed_see_package','claimedAbsoluteAccuracyMetres':None,'absoluteBoundaryAccuracyM':None,'independentInteriorControlCount':0,'namePointsUsedForGeoreferencing':False})
 if num==6:
  p.update({'literalBaseSourcePath':'remaining-literal-source-pixels.geojson','literalBaseWorldPath':'remaining-literal-world.geojson','literalBaseQuarantineReason':'hole_outside_shell: one1px source-mask hole touches exterior at a corner','inferenceProofPath':'remaining-iparterulet-one-pixel-inference-proof.json','currentQuarterIdentity':'unknown; exact contemporary OSM name not observed; historical table explicitly names Iparterület','literalBaseBoundaryIsObserved':True})
 else:
  p.update({'inferenceProofPath':'remaining-manual-reconstruction-proof.json','inferredCapSourcePath':'remaining-manual-caps-source-pixels.geojson','inferredCapAlternativesPath':'remaining-manual-cap-alternatives-source-pixels.geojson','literalOutsideAnnotationWindowIsObserved':True})
write('remaining-inferred-import.geojson',{'type':'FeatureCollection','features':sorted(fs,key=lambda f:f['properties']['sourceUnitNumber'])})
hash=hashlib.sha256((P/'remaining-inferred-import.geojson').read_bytes()).hexdigest()
base='data/neighborhoods/sources/municipal-zalaegerszeg-remaining-next/'
entry={'id':ID,'path':base+'remaining-inferred-import.geojson','sha256':hash,'municipality':'Zalaegerszeg','method':'Six explicit low-confidence source-based interpretations:five numbered quarter contours with small separately recorded label-occlusion caps, and two-part historical Iparterület with one original1px corner-touching hole explicitly filled as an estimated interpretation. Original raw6 contour and strict failure retained. Frozen inherited approximate municipal-perimeter affine with zero independent interior controls; unknown absolute accuracy.','evidenceUrls':['https://zalaegerszeg.hu/wp-content/uploads/2023/05/Zalaegerszeg_ITS.pdf'],'license':'Municipal map reuse rights not independently established; ODbL for archived OSM perimeter calibration and independent current-name evidence.','propertyOverrides':{'boundaryKind':'inferred_area','candidateBoundaryKind':'neighbourhood','estimated':True,'canonicalNameIsNeighborhood':False,'usableForAddressAssignment':False,'sourceContourIsObserved':False,'reconstructionConfidence':'low'},'reviewPath':base+'independent-source-registration-review.json','uncertainties':['The complete candidate boundaries include explicit inferred segments or a single-pixel ambiguity interpretation; neither is wholly observed source geometry.','The inherited affine has zero independent interior controls and unknown absolute accuracy. Cap lengths measure reconstructed hidden source segments, not positional accuracy.','The historical table explicitly defines Iparterület as unit6; no exact current OSM named-place match was observed, so current identity remains unknown. Industrial function alone is not an exclusion.','Ebergény southwest unlabelled lobe70 has low-confidence assignment; an alternative omitting it is retained. Bazita-adjacent unnumbered closed cell92 remains unassigned.','Source history/name evidence does not establish current legal boundaries or unrestricted map-reuse rights.'],'rightsStatus':'Municipal public publication; open map redistribution licence not independently established.','registryEntryAppliedByThisBatch':False}
write('remaining-registry-entry.json',entry)
print(json.dumps({'features':len(fs),'sha256':hash}))
